<?php
namespace App\Services\PageHelp;
use App\Enums\PageHelpAudience; use App\Models\PageHelp; use App\Models\User; use Illuminate\Support\Collection;
class PageHelpResolver { public function resolve(string $key, ?User $user=null, string $area='public'):Collection { return PageHelp::query()->published()->where('page_key',$key)->with(['roles:id,name','permissions:id,name'])->orderBy('sort_order')->get()->filter(fn(PageHelp $h)=>$this->visible($h,$user,$area))->values(); } public function visible(PageHelp $h,?User $u,string $area):bool { return match($h->audience){ PageHelpAudience::All=>true, PageHelpAudience::Public=>$area==='public', PageHelpAudience::Guest=>$u===null, PageHelpAudience::Authenticated=>$u!==null, PageHelpAudience::Member=>$u!==null && !$u->hasPermission('view_admin'), PageHelpAudience::Admin=>$u?->hasPermission('view_admin')??false, PageHelpAudience::Advertiser=>$u!==null && $u->advertiserMemberships()->where('is_active',true)->exists(), PageHelpAudience::Custom=>$u!==null && ($h->roles->pluck('name')->intersect($u->roleNames())->isNotEmpty() || $h->permissions->pluck('name')->intersect($u->allPermissionNames())->isNotEmpty()), }; } }
